  'expeller pressed high oleic safflower oil': { risk: IngredientRisk.Low, category: 'fats', explanation: 'High-oleic safflower oil mechanically pressed without chemical solvents; ~75% oleic acid, oxidatively stable, and lower in omega-6 than regular safflower oil.' },
  'expeller pressed sunflower oil': { risk: IngredientRisk.Medium, category: 'fats', explanation: 'Conventionally bred sunflower oil (not high-oleic) extracted by mechanical press; high in omega-6 linoleic acid (~65%), which may promote inflammation at excess intake.' },
  'expeller pressed canola oil': { risk: IngredientRisk.Medium, category: 'fats', explanation: 'Canola oil extracted mechanically without chemical solvents; avoids hexane residue but retains the same fatty acid profile as refined canola — moderate omega-6 content.' },
  'non-gmo expeller pressed canola oil': { risk: IngredientRisk.Medium, category: 'fats', explanation: 'Non-GMO canola oil mechanically pressed without solvent extraction; same fatty acid profile as conventional canola with no GMO cultivation and no hexane residue.' },
  'organic canola oil': { risk: IngredientRisk.Medium, category: 'fats', explanation: 'Certified organic canola oil from non-GMO seed; same fatty acid composition as conventional canola — moderate omega-6 — but grown without synthetic pesticides.' },
  'organic sunflower oil': { risk: IngredientRisk.Medium, category: 'fats', explanation: 'Certified organic sunflower oil; high in omega-6 linoleic acid at typical serving levels — same fatty acid concerns as conventional sunflower oil, grown without synthetic pesticides.' },
  'organic coconut oil': { risk: IngredientRisk.Medium, category: 'fats', explanation: 'Certified organic cold-pressed coconut oil; ~90% saturated fat, primarily lauric acid — the AHA recommends limiting saturated fat intake, though lauric acid has a different metabolic profile than long-chain saturated fats.' },
  'organic virgin coconut oil': { risk: IngredientRisk.Medium, category: 'fats', explanation: 'Unrefined virgin coconut oil retaining more polyphenols than refined versions; still ~90% saturated fat — use in moderation per AHA saturated fat guidelines.' },
  'olive pomace oil': { risk: IngredientRisk.Medium, category: 'fats', explanation: 'Residual oil extracted from olive pulp using solvents after pressing; lower in polyphenols than EVOO and may contain trace polycyclic aromatic hydrocarbons — approved by FDA but considered a lower-grade olive oil.' },
  'pure olive oil': { risk: IngredientRisk.Low, category: 'fats', explanation: 'Refined olive oil blended with a small amount of extra virgin; lower in polyphenols than EVOO but still predominantly oleic acid with a good monounsaturated fatty acid profile.' },
  'palm fruit oil': { risk: IngredientRisk.Medium, category: 'fats', explanation: 'Oil from the palm fruit mesocarp; ~50% saturated fat (primarily palmitic acid) which the AHA links to elevated LDL cholesterol, plus significant deforestation and biodiversity concerns.' },
  'organic palm fruit oil': { risk: IngredientRisk.Medium, category: 'fats', explanation: 'Certified organic palm oil; same ~50% saturated fat profile as conventional palm oil — certified sustainable sourcing reduces (but does not eliminate) deforestation concerns.' },
