  'hydrogenated vegetable oil': { risk: IngredientRisk.High, category: 'fats', explanation: 'Partially hydrogenated vegetable oil creates trans fats, which the FDA has determined have no safe level of consumption; fully hydrogenated versions avoid trans fats but are very high in saturated fat.' },
  'fully hydrogenated soybean oil': { risk: IngredientRisk.Medium, category: 'fats', explanation: 'Completely hydrogenated soybean oil with no double bonds remaining; does not contain trans fats (unlike partially hydrogenated) but is very high in saturated stearic acid — often used as a trans-fat-free shortening.' },
  'fully hydrogenated cottonseed oil': { risk: IngredientRisk.Medium, category: 'fats', explanation: 'Fully hydrogenated cottonseed oil used as a trans-fat-free shortening base; high in saturated stearic acid — no trans fats but contributes to total saturated fat intake.' },
  'fully hydrogenated rapeseed oil': { risk: IngredientRisk.Medium, category: 'fats', explanation: 'Completely hydrogenated canola/rapeseed oil; no trans fats but very high in saturated stearic acid — used as a structural fat in confectionery coatings and shortenings.' },
  'medium chain triglycerides': { risk: IngredientRisk.Low, category: 'fats', explanation: 'MCT oil derived from coconut or palm kernel oil; rapidly absorbed and metabolized for energy, not stored as body fat at the same rate as long-chain fats — FDA GRAS, widely used in clinical nutrition.' },
  'garlic oil': { risk: IngredientRisk.Low, category: 'fats', explanation: 'Oil infused with or extracted from garlic; contains organosulfur compounds with documented antimicrobial and cardiovascular benefits at food-use levels.' },
