  'cultured celery extract': { risk: IngredientRisk.Low, category: 'preservatives', explanation: 'Fermented celery juice extract used for natural curing; produces nitrites from naturally occurring celery nitrates — functionally identical to direct nitrite curing despite "natural" labeling.' },
  'rosemary extract (antioxidant)': { risk: IngredientRisk.Low, category: 'preservatives', explanation: 'Concentrated extract of Rosmarinus officinalis containing carnosic acid and rosmarinic acid; natural antioxidant preservative — FDA GRAS, may have modest anti-inflammatory benefits.' },
  'rosemary extract (for freshness)': { risk: IngredientRisk.Low, category: 'preservatives', explanation: 'Rosemary-derived antioxidant for oil freshness; prevents rancidity without synthetic antioxidants — FDA GRAS, a clean-label alternative to BHA/BHT.' },
