  'bha': { risk: IngredientRisk.High, category: 'preservatives', explanation: 'Butylated hydroxyanisole (E320); synthetic antioxidant preservative — listed as "reasonably anticipated to be a human carcinogen" by the US National Toxicology Program based on animal studies. EU requires "may have an adverse effect on activity and attention in children" if in combination with certain dyes.' },
  'bht': { risk: IngredientRisk.High, category: 'preservatives', explanation: 'Butylated hydroxytoluene (E321); synthetic antioxidant preservative — National Toxicology Program lists it as "reasonably anticipated to be a human carcinogen"; some research suggests endocrine disruption at high doses. EU restricts its use more than the FDA.' },
  'bht added to packaging material to preserve freshness': { risk: IngredientRisk.High, category: 'preservatives', explanation: 'BHT applied to food packaging that migrates into the food; same carcinogen concern as direct BHT addition — the migration from packaging is considered lower exposure but still classified as high risk given the NTP carcinogen designation.' },
  'dipotassium phosphate': { risk: IngredientRisk.Low, category: 'additives', explanation: 'Potassium phosphate salt used as a buffering agent and electrolyte; FDA GRAS — frequently used in coffee creamers and sports drinks. At food-use levels no significant concern, though total phosphate intake from multiple processed foods deserves monitoring.' },
  'dipotassium phosphate (electrolyte)': { risk: IngredientRisk.Low, category: 'additives', explanation: 'Dipotassium phosphate added as an electrolyte; FDA GRAS — provides potassium for hydration products at levels that are generally safe.' },
  'potassium lactate (to preserve freshness)': { risk: IngredientRisk.Low, category: 'preservatives', explanation: 'Potassium salt of lactic acid; antimicrobial preservative — FDA GRAS (21 CFR 184.1639), naturally derived source of lactic acid with good safety profile.' },
  'sodium phosphates': { risk: IngredientRisk.Medium, category: 'additives', explanation: 'Various sodium phosphate salts (monobasic, dibasic, tribasic); used for moisture retention, emulsification, and pH buffering — FDA GRAS but cumulative phosphate intake from multiple processed foods can stress kidneys and disrupt the calcium-to-phosphorus balance.' },
  'encapsulated lactic acid': { risk: IngredientRisk.Low, category: 'additives', explanation: 'Microencapsulated lactic acid for controlled release in baking; the lactic acid itself is FDA GRAS and naturally produced in fermented foods — encapsulation technology allows precise leavening timing.' },
