  'caffeine': { risk: IngredientRisk.Medium, category: 'additives', explanation: 'Added caffeine from synthetic sources; FDA considers up to 400mg/day safe for healthy adults but recommends pregnant women limit to <200mg/day — added caffeine in products is regulated and must be declared on labels of products marketed to children.' },
  'natural caffeine': { risk: IngredientRisk.Medium, category: 'additives', explanation: 'Caffeine from natural sources (green coffee, guarana, tea); same physiological effects as synthetic caffeine — same 400mg/day adult safety guideline applies regardless of source.' },
