  'panax ginseng root extract': { risk: IngredientRisk.Low, category: 'additives', explanation: 'Concentrated ginsenoside-rich Panax ginseng extract; adaptogenic herb with clinical evidence for cognitive function support — FDA GRAS at food-use levels.' },
